            [6565] = "검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.",
            [6626] = "가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다.",
            [6627] = "브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.",
            [6628] = "파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다.",
            [6921] = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.",
            [92401] = "로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.",
            [92415] = "피로 얼룩진 편지를 스톰윈드에 있는 보육원 원장님 나이팅게일에게 가져가야 합니다.",
            [92421] = "언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다.",
            [92422] = "브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다.",
            [92742] = "얀센 농장과 몰센 농장 우물에서 우물물 표본 채취 도구를 사용해 표본을 채취해야 합니다.",
            [92744] = "서부 몰락지대 해안선에서 기나긴 해안 멀록 아가미 7개를 입수해 알바 페어문에게 전달해야 합니다.",
            [92745] = "장고로드 광산에서 코볼트 채굴꾼 4마리를, 황금해안 채석장에서 갈퀴발 광부 6마리를 처치해야 합니다.",
