            [92748] = "스톰윈드 드워프 지구로 이동한 후 도움을 줄 수 있는 기술자를 찾아야 합니다.",
            [92749] = "제작이나 거래, 경매장을 통해 일반 다이너마이트 10개를 입수한 후, 스톰윈드 드워프 지구에 있는 스프라이트 점프스프로켓에게 가야 합니다.",
            [92750] = "스톰윈드 첩보부 구성원을 찾아가 원격 기폭장치에 관해 얘기해야 합니다.",
            [92751] = "원격 기폭장치 도구를 스톰윈드 드워프 지구에 있는 스프라이트 점프스프로켓에게 가져가야 합니다.",
